#include "sleela/compiler.hpp"
#include <cstdlib>
#include <iostream>
#include <fstream>
#include <filesystem>
#include <iterator>
int main(){using namespace sleela::compiler;int fail=0;auto check=[&](bool x,const char*m){if(!x){std::cerr<<"FAIL "<<m<<'\n';++fail;}};auto p=compile("let a = 6 * 7; print a; return a + 1;");check(p.ok(),"compile arithmetic");auto r=run(p);check(r.ok(),"run");check(r.printed_values.size()==1&&r.printed_values[0]==42,"print 42");check(r.return_value==43,"return 43");check(!compile("print unknown;").ok(),"unknown variable");check(!compile("let a = 1; let a = 2;").ok(),"duplicate variable");auto z=run(compile("print 1 / 0;"));check(!z.ok()&&z.error=="division by zero","division by zero");auto q=run(compile("print (2 + 3) * -4;"));check(q.ok()&&q.printed_values.size()==1&&q.printed_values[0]==-20,"precedence");check(!compile("print 1").ok(),"semicolon required");auto overflow=run(compile("print 9223372036854775807 + 1;"));check(!overflow.ok()&&overflow.error=="addition overflow","addition overflow");auto negOverflow=run(compile("let min = -9223372036854775807 - 1; print -min;"));check(!negOverflow.ok()&&negOverflow.error=="negation overflow","negation overflow");auto mulOverflow=run(compile("print 3037000500 * 3037000500;"));check(!mulOverflow.ok()&&mulOverflow.error=="multiplication overflow","multiplication overflow");auto nativeProgram=compile("let answer = 6 * 7; print answer; return answer;");auto nativePath=std::filesystem::temp_directory_path()/"sleela-generated-test.c";std::string nativeError;check(write_native_source(nativeProgram,nativePath,false,nativeError),"emit C source");std::ifstream nativeFile(nativePath);std::string nativeText((std::istreambuf_iterator<char>(nativeFile)),{});check(nativeText.find("int main(void)")!=std::string::npos,"generated C has entry point");check(nativeText.find("case 9:")!=std::string::npos,"generated C has print opcode");check(nativeText.find("pc>=SL_PROGRAM_COUNT")!=std::string::npos,"generated C bounds-checks program counter");check(!write_native_source(compile("print missing;"),nativePath,false,nativeError),"refuse native emission after failed compilation");nativeFile.close();std::ifstream preservedFile(nativePath);std::string preservedText((std::istreambuf_iterator<char>(preservedFile)),{});check(preservedText==nativeText,"failed emission preserves existing output");preservedFile.close();std::filesystem::remove(nativePath);if(fail)return EXIT_FAILURE;std::cout<<"All native compiler tests passed\n";return EXIT_SUCCESS;}
